import{_ as t,o as r,c as e,a5 as n}from"./chunks/framework.CcrBcQWS.js";const g=JSON.parse('{"title":"운영 환경 요구사항","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/safety/operating-environment-requirements.md","filePath":"ko/manual/safety/operating-environment-requirements.md","lastUpdated":1787021357000}'),o={name:"ko/manual/safety/operating-environment-requirements.md"};function s(i,a,l,d,h,u){return r(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="운영-환경-요구사항" tabindex="-1">운영 환경 요구사항 <a class="header-anchor" href="#운영-환경-요구사항" aria-label="Permalink to &quot;운영 환경 요구사항&quot;">​</a></h1><p>RBQ는 실내·일반 작업장뿐 아니라 위험 작업 환경, 군용, 순찰·점검 등 <strong>다양한 환경</strong>에서 활용되는 4족 보행 로봇입니다.</p><ul><li><strong>아래 내용</strong>: 일반 사용 시 권장 환경과 사양서 기준입니다.</li><li><strong>특수 환경</strong>(위험 작업장, 군용, 무인 순찰 등) 사용 시에는 별도 위험 평가와 추가 조치가 필요할 수 있습니다.</li></ul><h2 id="권장-환경-일반-사용" tabindex="-1">권장 환경(일반 사용) <a class="header-anchor" href="#권장-환경-일반-사용" aria-label="Permalink to &quot;권장 환경(일반 사용)&quot;">​</a></h2><p>다음 조건은 로봇의 정상 동작과 수명 유지를 위해 권장되는 환경입니다. 이 조건을 충족할 때 성능과 보증이 적용됩니다.</p><h3 id="온도·습도" tabindex="-1">온도·습도 <a class="header-anchor" href="#온도·습도" aria-label="Permalink to &quot;온도·습도&quot;">​</a></h3><ul><li><strong>사용·보관 온도</strong>: 매뉴얼 또는 사양에 명시된 작동·보관 온도 범위를 지키세요. 그 밖의 환경에서는 성능 저하·고장·배터리 수명 단축이 발생할 수 있습니다.</li><li><strong>습도</strong>: 과습·결로가 심한 환경에서는 센서·전기 부품에 영향을 줄 수 있으므로, 가능한 한 지정된 습도 범위 내에서 사용·보관하세요.</li></ul><h3 id="바닥·작업-공간" tabindex="-1">바닥·작업 공간 <a class="header-anchor" href="#바닥·작업-공간" aria-label="Permalink to &quot;바닥·작업 공간&quot;">​</a></h3><ul><li><strong>평탄도</strong>: 로봇은 지정된 수준의 평탄하고 견고한 바닥에서 사용할 때 가장 안정적입니다. 과도한 경사·요철·미끄러운 면에서는 넘어지거나 제어가 불안정해질 수 있습니다.</li><li><strong>공간</strong>: 로봇이 이동·자세 보정·넘어짐 복구를 할 수 있는 충분한 공간을 확보하면 안전합니다. <strong>운용 중에는 로봇 반경 2m 안에 사람·동물(반려동물 포함)이 들어오면 안 됩니다.</strong> 장애물과의 간격도 안전 기준에 맞게 유지하세요.</li></ul><h3 id="전자기·물리-환경" tabindex="-1">전자기·물리 환경 <a class="header-anchor" href="#전자기·물리-환경" aria-label="Permalink to &quot;전자기·물리 환경&quot;">​</a></h3><ul><li><strong>자기장</strong>: 강한 자기장이 있는 곳에서는 센서·제어에 영향을 줄 수 있으므로, 가능한 한 사용을 피하세요.</li><li><strong>진동·충격</strong>: 과도한 진동·충격이 있는 환경에서는 고장·오측정의 원인이 될 수 있으므로, 가능한 한 완충·격리하거나 사용을 제한하세요.</li></ul><h3 id="위험-환경" tabindex="-1">위험 환경 <a class="header-anchor" href="#위험-환경" aria-label="Permalink to &quot;위험 환경&quot;">​</a></h3><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>폭발 위험 구역·가연성 가스·분진 환경에서는 사용하지 마세요. 방수 등급이 명시되지 않은 경우, 실외·비·분수 근처에서는 <strong>사용하지 마세요</strong>(사용 금지).</p></div></div><h2 id="특수·한계-환경에서의-사용" tabindex="-1">특수·한계 환경에서의 사용 <a class="header-anchor" href="#특수·한계-환경에서의-사용" aria-label="Permalink to &quot;특수·한계 환경에서의 사용&quot;">​</a></h2><p>위험 작업장, 군용, 무인 순찰, 재난 현장·접근 곤란 지역 점검 등에서는 <strong>온도·습도·바닥·공간</strong> 등 사양서 조건을 충족하기 어렵거나, 예측하기 어려운 위험 요소가 있을 수 있습니다.<br> 해당 용도로 RBQ를 사용할 경우에는 <strong>사용 전 위험 평가</strong>를 수행하고, 필요한 <strong>추가 안전 장치·운용 절차·보호 장비</strong>를 적용한 뒤 사용하세요. 사양서에 명시된 환경을 벗어난 사용으로 인한 고장·손상에 대해서는 보증이 적용되지 않을 수 있습니다.</p><p>Rainbow Robotics에 연락하세요. <a href="/RBQ/nightly/ko/manual/troubleshooting/error-reporting.html">문의하기</a> 페이지를 참고하세요.</p>',16)])])}const p=t(o,[["render",s]]);export{g as __pageData,p as default};
